package com.dennis.aimasteringlab;
import org.json.JSONObject;import java.io.*;
/** Controlled host regression for all five v0.9 systems and source guards. */
public final class V09MasteringHarness{
 public static void main(String[]a)throws Exception{if(a.length!=2)throw new IllegalArgumentException();File f=new File(a[0]),out=new File(a[1]);out.mkdirs();File source=new File(f,"source.wav"),reference=new File(f,"reference.wav");AnalysisResult s=analyze(source);s.sourceGuard=SourceGuardModel.analyze(p(source),s,(x,y)->{});require(!s.sourceGuard.artificial24From16&&s.sourceGuard.effectiveBits>=23,"clean guard false positive");File artificialFile=new File(f,"artificial.wav");AnalysisResult art=analyze(artificialFile);require(SourceGuardModel.analyze(p(artificialFile),art,(x,y)->{}).artificial24From16,"24-from-16 missed");File lossyFile=new File(f,"lossy.wav");AnalysisResult lossy=analyze(lossyFile);SourceGuardModel.Result lg=SourceGuardModel.analyze(p(lossyFile),lossy,(x,y)->{});require(lg.bandwidthCutoffDetected&&lg.likelyLossyInWav&&lg.highBoostBlocked,"lossy guard missed");File priorFile=new File(f,"Song_FullAI24.wav");AnalysisResult prior=analyze(priorFile);SourceGuardModel.Result pg=SourceGuardModel.analyze(p(priorFile),prior,(x,y)->{});require(pg.likelyPriorDennisMaster&&pg.secondPassGuard&&!prior.limiterAllowed,"second-pass guard missed");
 s.nextGenerationIntelligence=NextGenerationMasteringModel.analyze(p(source),s,p(reference),reference.getName(),Hashing.sha256(reference),(x,y)->{});NextGenerationMasteringModel.Result m=s.nextGenerationIntelligence;require(m.translation.automaticCount()>0&&m.tones.automaticCount()>0&&m.channel.automaticCount()>0&&m.reference.automaticCount()>0,"all systems did not activate");for(TranslationConsensusModel.Event e:m.translation.events)if(e.automatic){boolean ok=e.kind==TranslationConsensusModel.Kind.VOCAL_MASKING?((e.familyCount>=2&&e.deviceCount>=3)||(e.familyCount==1&&e.deviceCount>=3)):(e.familyCount>=3&&e.deviceCount>=3);require(ok&&e.familyEvidence!=null&&e.deviceEvidence!=null,"unmeasured translation consensus");}
 File singleFile=new File(f,"single.wav");require(PersistentToneModel.analyze(p(singleFile),analyze(singleFile),(x,y)->{}).automaticCount()==0,"musical tone removed");File humFile=new File(f,"hum.wav");require(PersistentToneModel.analyze(p(humFile),analyze(humFile),(x,y)->{}).automaticCount()>=3,"hum missed");File buzzFile=new File(f,"buzz.wav");require(PersistentToneModel.analyze(p(buzzFile),analyze(buzzFile),(x,y)->{}).automaticCount()>=3,"buzz missed");File polFile=new File(f,"polarity.wav");require(ChannelIntegrityModel.analyze(p(polFile),analyze(polFile),(x,y)->{}).automaticCount()>0,"polarity missed");File delayFile=new File(f,"delay.wav");boolean delay=false;for(ChannelIntegrityModel.Event e:ChannelIntegrityModel.analyze(p(delayFile),analyze(delayFile),(x,y)->{}).events)if(e.kind==ChannelIntegrityModel.Kind.FIXED_DELAY&&e.automatic)delay=true;require(delay,"delay missed");
 AutonomousMasteringBrain.Result brain=AutonomousMasteringBrain.analyze(p(source),s,null,(x,y)->{});AutonomousMasteringBrain.Plan transparent=null;for(AutonomousMasteringBrain.Plan q:brain.internalPlans)if("transparent_flat_gain".equals(q.strategy))transparent=q;require(transparent!=null,"baseline missing");int rendered=0;for(NextGenerationMasteringRenderer.Mode mode:NextGenerationMasteringRenderer.Mode.values()){boolean available=mode==NextGenerationMasteringRenderer.Mode.TRANSLATION_CONSENSUS?m.translation.automaticCount()>0:mode==NextGenerationMasteringRenderer.Mode.PERSISTENT_TONE_REPAIR?m.tones.automaticCount()>0:mode==NextGenerationMasteringRenderer.Mode.CHANNEL_INTEGRITY?m.channel.automaticCount()>0:mode==NextGenerationMasteringRenderer.Mode.REFERENCE_AWARE?m.reference.automaticCount()>0:m.availableModules()>=2;if(!available)continue;NextGenerationMasteringRenderer.Result rr=NextGenerationMasteringRenderer.render(p(source),s,transparent,mode,new File(out,mode.strategy+".wav"),out,(x,y)->{});AnalysisResult v=rr.render.master.verification;require(v.wav.frames==s.wav.frames&&v.wav.bitsPerSample==24&&v.truePeakEstimateDbtp<=-1&&v.clippedSamples==0&&rr.delta.protectedRegionsExact&&!rr.wideningUsed,"render safety "+mode);rendered++;}require(rendered>=4,"render coverage");
 FullAiMasteringEngine.Result engine=FullAiMasteringEngine.run(p(source),s,brain,null,new File(out,"competition"),null,null,(x,y)->{});require(engine.nextGenerationCandidatesAttempted>=2,"narrow competition missing");require(engine.translationConsensusDiagnosticOnly&&engine.naturalReference!=null,"natural policy missing");for(FullAiMasteringEngine.Candidate c:engine.candidates)if(c.nextGenerationAware)require(c.nextGenerationMode!=NextGenerationMasteringRenderer.Mode.TRANSLATION_CONSENSUS&&c.nextGenerationMode!=NextGenerationMasteringRenderer.Mode.V09_COMBINED,"translation or stacked v0.9 candidate rendered");prior.nextGenerationIntelligence=NextGenerationMasteringModel.analyze(p(priorFile),prior,null,null,null,(x,y)->{});AutonomousMasteringBrain.Result pb=AutonomousMasteringBrain.analyze(p(priorFile),prior,null,(x,y)->{});FullAiMasteringEngine.Result pe=FullAiMasteringEngine.run(p(priorFile),prior,pb,null,new File(out,"second-pass"),null,null,(x,y)->{});require(pe.intelligenceCandidatesAttempted==0&&pe.advancedCandidatesAttempted==0&&pe.professionalCandidatesAttempted==0&&pe.stemCandidatesAttempted==0,"broad second pass rendered");for(FullAiMasteringEngine.Candidate c:pe.candidates)if(c.nextGenerationAware)require(c.nextGenerationMode==NextGenerationMasteringRenderer.Mode.PERSISTENT_TONE_REPAIR||c.nextGenerationMode==NextGenerationMasteringRenderer.Mode.CHANNEL_INTEGRITY,"nontechnical second pass");
 FullAiReleaseQc.Result qc=new FullAiReleaseQc.Result();qc.initialPcmWinner=engine.selected;qc.finalCandidate=engine.selected;qc.finalMaster=engine.selected.file;qc.finalMasterVerification=engine.selected.render.master.verification;qc.finalMasterSha256=Hashing.sha256(qc.finalMaster);qc.technicalVerdict="PASS";qc.translationVerdict="PASS";JSONObject json=new JSONObject(FullAiReportWriter.create(s,brain,engine,qc));require("0.9.1".equals(json.getString("version"))&&!json.isNull("source_guard")&&!json.isNull("v09_source_aware_intelligence")&&!json.getJSONObject("v09_source_aware_intelligence").getBoolean("translation_candidate_generation_enabled"),"QC schema");System.out.println("V09_MASTERING_PASS translation="+m.translation.automaticCount()+" tones="+m.tones.automaticCount()+" channel="+m.channel.automaticCount()+" reference="+m.reference.automaticCount()+" secondPass="+pe.selected.strategy);}
 private static AnalysisResult analyze(File f)throws Exception{return AudioAnalyzer.analyze(f.getName(),p(f),(x,y)->{});}private static AudioAnalyzer.StreamProvider p(File f){return()->new FileInputStream(f);}private static void require(boolean c,String m){if(!c)throw new AssertionError(m);}
}
